def list_curated_scripts():
    """Prints a structured catalog table of all curated scripts."""
    print("=" * 86)
    print("MASTER CURATED SCRIPTS COMPENDIUM: RANGE INTELLIGENCE COURSE PROJECT")
    print("=" * 86)
    print(f"{'#':<3} | {'Script Name':<28} | {'Category':<22} | {'Origin':<18} | {'Lines':>5} | {'Size'}")
    print("-" * 86)
    total_lines = 0
    total_bytes = 0
    for idx, (name, meta) in enumerate(CURATED_SCRIPTS.items(), 1):
        lines = meta["lines"]
        sz_kb = f"{meta['bytes'] / 1024:.1f} KB"
        total_lines += lines
        total_bytes += meta["bytes"]
        print(f"{idx:02d} | {name:<28} | {meta['category']:<22} | {meta['origin']:<18} | {lines:>5} | {sz_kb:>7}")
    print("-" * 86)
    print(f"TOTAL: {len(CURATED_SCRIPTS)} scripts | {total_lines:,} lines of code | {total_bytes / 1024:.1f} KB")
    print("=" * 86)
    print("\nFor full script details and execution options, run:")
    print("  python curated_all_scripts.py --help")
    print("  python curated_all_scripts.py --show <script_name>")
    print("  python curated_all_scripts.py --extract [output_directory]")


def show_script_source(script_name):
    """Displays the exact source code of the requested script."""
    if script_name not in CURATED_SCRIPTS:
        matches = [k for k in CURATED_SCRIPTS if script_name.lower() in k.lower()]
        if len(matches) == 1:
            script_name = matches[0]
        else:
            print(f"[!] Error: Script '{script_name}' not found.")
            if matches:
                print(f"    Did you mean one of: {', '.join(matches)}?")
            else:
                print("    Use --list to view all available scripts.")
            return

    meta = CURATED_SCRIPTS[script_name]
    print("=" * 80)
    print(f"SCRIPT: {script_name}")
    print(f"CATEGORY: {meta['category']} | ORIGIN: {meta['origin']}")
    print(f"DESCRIPTION: {meta['description']}")
    print("=" * 80)
    print(meta["source"])
    print("=" * 80)
    print(f"[+] End of {script_name} ({meta['lines']} lines, {meta['bytes'] / 1024:.1f} KB)")


def extract_all_scripts(target_dir="curated_scripts_bundle"):
    """Extracts all 15 curated scripts to the specified folder."""
    os.makedirs(target_dir, exist_ok=True)
    print(f"[*] Extracting all {len(CURATED_SCRIPTS)} scripts to: {os.path.abspath(target_dir)}")
    for name, meta in CURATED_SCRIPTS.items():
        out_path = os.path.join(target_dir, name)
        with open(out_path, "w", encoding="utf-8") as f:
            f.write(meta["source"])
        print(f"  [+] Extracted: {name:<28} ({meta['lines']:>4} lines) -> {out_path}")
    print(f"\n[+] Successfully extracted {len(CURATED_SCRIPTS)} scripts to '{target_dir}'.")


def export_markdown_compendium(output_path="CURATED_SCRIPTS.md"):
    """Generates a complete GitHub-flavored Markdown compendium of all scripts."""
    print(f"[*] Generating Markdown documentation compendium: {output_path}...")
    with open(output_path, "w", encoding="utf-8") as f:
        f.write("# Master Curated Scripts Compendium\\n\\n")
        f.write("## Range Intelligence: Battery Degradation-Aware EV Fleet Charging Recommendation and Infrastructure Optimization\\n\\n")
        f.write("**Department:** Computer Science & Engineering (Data Science), Vishwakarma Institute of Technology, Pune  \\n")
        f.write("**Academic Year:** 2025 - 2026 | **Date:** 16/11/2026  \\n")
        f.write("**Group:** 14  \\n")
        f.write("**Team Members:** Sumit Gavali (44), Rudrasingh Dikshit (38), Ronit Jain (57), Ashraf Ahmed (09)  \\n")
        f.write("**Supervisor:** Prof. Dr. Rupali Mahajan | **HOD:** Dr. Deepa Abin  \\n\\n")
        f.write("---\\n\\n")
        f.write("### Table of Curated Scripts\\n\\n")
        f.write("| # | Script Name | Category | Origin | Lines | Size |\\n")
        f.write("|---|-------------|----------|--------|-------|------|\\n")
        for idx, (name, meta) in enumerate(CURATED_SCRIPTS.items(), 1):
            f.write(f"| {idx:02d} | [`{name}`](#{name.lower().replace('.', '').replace('_', '-')}) | {meta['category']} | {meta['origin']} | {meta['lines']} | {meta['bytes'] / 1024:.1f} KB |\\n")
        f.write("\\n---\\n\\n")

        for idx, (name, meta) in enumerate(CURATED_SCRIPTS.items(), 1):
            f.write(f"## {idx}. {name}\\n\\n")
            f.write(f"- **Category:** `{meta['category']}`\\n")
            f.write(f"- **Origin:** `{meta['origin']}`\\n")
            f.write(f"- **Description:** {meta['description']}\\n\\n")
            f.write("```python\\n")
            f.write(meta["source"])
            if not meta["source"].endswith("\\n"):
                f.write("\\n")
            f.write("```\\n\\n---\\n\\n")
    print(f"[+] Markdown documentation successfully generated at: {os.path.abspath(output_path)}")


def run_extracted_script(script_name, args=None):
    """Executes a curated script inside a temporary execution sandbox."""
    if script_name not in CURATED_SCRIPTS:
        print(f"[!] Error: Script '{script_name}' is not in the curated registry.")
        return 1

    with tempfile.TemporaryDirectory() as tmpdir:
        # Extract dependencies needed for report build scripts
        for dep_name in ["report_content.py", "report_tables_data_v8.py", "report_equations_v8.py", "report_chapters_v8.py"]:
            if dep_name in CURATED_SCRIPTS:
                with open(os.path.join(tmpdir, dep_name), "w", encoding="utf-8") as f:
                    f.write(CURATED_SCRIPTS[dep_name]["source"])

        target_path = os.path.join(tmpdir, script_name)
        with open(target_path, "w", encoding="utf-8") as f:
            f.write(CURATED_SCRIPTS[script_name]["source"])

        cmd = [sys.executable, target_path] + (args or [])
        print(f"[*] Executing {script_name} via: {' '.join(cmd)}")
        res = subprocess.run(cmd, cwd=os.getcwd())
        return res.returncode


def main():
    parser = argparse.ArgumentParser(
        description="Master Curated Scripts Compendium - Range Intelligence Course Project",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog="""
Examples:
  python curated_all_scripts.py --list
  python curated_all_scripts.py --show build_full_report_v8.py
  python curated_all_scripts.py --extract ./my_scripts
  python curated_all_scripts.py --markdown CURATED_SCRIPTS.md
  python curated_all_scripts.py --build-report
  python curated_all_scripts.py --build-figures
  python curated_all_scripts.py --audit
"""
    )
    parser.add_argument("--list", "-l", action="store_true", help="List all 15 curated scripts and metadata")
    parser.add_argument("--show", "-s", metavar="NAME", help="Display full source code of a specific script")
    parser.add_argument("--extract", "-e", nargs="?", const="curated_scripts_bundle", metavar="DIR", help="Extract all scripts into specified folder (default: ./curated_scripts_bundle)")
    parser.add_argument("--markdown", "-m", nargs="?", const="CURATED_SCRIPTS.md", metavar="FILE", help="Generate single Markdown documentation file (default: CURATED_SCRIPTS.md)")
    parser.add_argument("--build-report", action="store_true", help="Execute master 2-pass report compiler (build_full_report_v8.py)")
    parser.add_argument("--build-figures", action="store_true", help="Execute Chapter 8 figure builder (build_chapter8_figures.py)")
    parser.add_argument("--audit", action="store_true", help="Execute PDF institutional compliance auditor (audit_final_report_pdf.py)")

    if len(sys.argv) == 1:
        list_curated_scripts()
        return

    args = parser.parse_args()

    if args.list:
        list_curated_scripts()
    elif args.show:
        show_script_source(args.show)
    elif args.extract:
        extract_all_scripts(args.extract)
    elif args.markdown:
        export_markdown_compendium(args.markdown)
    elif args.build_report:
        run_extracted_script("build_full_report_v8.py")
    elif args.build_figures:
        run_extracted_script("build_chapter8_figures.py")
    elif args.audit:
        run_extracted_script("audit_final_report_pdf.py")


if __name__ == "__main__":
    main()
